def fraction_to_decimal(numerator: int, denominator: int) -> str:
    if denominator == 0:
        return '0'

    result = []
    if numerator < 0 and denominator > 0 or numerator > 0 and denominator < 0:
        result.append('-')

    numerator, denominator = abs(numerator), abs(denominator)
    integer_part, numerator = divmod(numerator, denominator)
    result.append(str(integer_part))

    if numerator == 0:
        return ''.join(result)

    result.append('.')
    decimal_part = []
    seen = {}

    while numerator != 0:
        if numerator in seen:
            decimal_part.insert(seen[numerator], '(')
            decimal_part.append(')')
            break

        seen[numerator] = len(decimal_part)
        quotient, numerator = divmod(numerator * 10, denominator)
        decimal_part.append(str(quotient))

    return ''.join(result + decimal_part)

