def get_skyline(buildings: list) -> list:
    if not buildings:
        return []

    events = []
    for left, right, height in buildings:
        events.append((left, -height, right))  # start of building
        events.append((right, 0, None))  # end of building

    events.sort()

    res = [[0, 0]]
    heap = [(0, float('inf'))]  # (height, rightmost x)
    for x, neg_height, right in events:
        if neg_height < 0:  # start of building
            heapq.heappush(heap, (neg_height, right))
        else:  # end of building
            while heap and heap[0][1] <= x:
                heapq.heappop(heap)

        if res[-1][1] != -heap[0][0]:
            res.append([x, -heap[0][0]])

    return res[1:]

