def critical_connections(n: int, connections: list) -> list:
    def dfs(node, discovery_time, low_time, time, visited, bridges, graph):
        visited[node] = True
        nonlocal time
        discovery_time[node] = low_time[node] = time
        time += 1
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, discovery_time, low_time, time, visited, bridges, graph)
                low_time[node] = min(low_time[node], low_time[neighbor])
                if low_time[neighbor] > discovery_time[node]:
                    bridges.append((node, neighbor))
            else:
                low_time[node] = min(low_time[node], discovery_time[neighbor])

    bridges = []
    visited = [False] * n
    discovery_time = [0] * n
    low_time = [0] * n
    graph = {i: [] for i in range(n)}
    for conn in connections:
        graph[conn[0]].append(conn[1])
        graph[conn[1]].append(conn[0])

    for i in range(n):
        if not visited[i]:
            dfs(i, discovery_time, low_time, 0, visited, bridges, graph)

    return bridges

def critical_connections(n: int, connections: list) -> list:
    if not connections:
        return []

    id_counter = 0
    low = [0] * n
    id = [0] * n
    on_stack = [False] * n
    result = []
    graph = [[] for _ in range(n)]

    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node: int, parent: int) -> None:
        nonlocal id_counter
        id_counter += 1
        id[node] = low[node] = id_counter
        on_stack[node] = True

        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if not id[neighbor]:
                dfs(neighbor, node)
                low[node] = min(low[node], low[neighbor])
                if low[neighbor] > id[node]:
                    result.append([node, neighbor])
            elif on_stack[neighbor]:
                low[node] = min(low[node], id[neighbor])

        on_stack[node] = False

    for i in range(n):
        if not id[i]:
            dfs(i, -1)

    return result

