        if expression[i] == 't':
            stack.append(True)
        elif expression[i] == 'f':
            stack.append(False)
        elif expression[i] == '!':
            stack.append(not stack.pop())
        elif expression[i] == '&':
            b, a = stack.pop(), stack.pop()
            stack.append(a and b)
        elif expression[i] == '|':
            b, a = stack.pop(), stack.pop()
            stack.append(a or b)
        i += 1
    return stack[0]

def parse_bool_expr(expression: str) -> bool:
    import re

    # Define the mapping of boolean values
    bool_map = {'t': True, 'f': False}

    # Helper function to evaluate a single boolean expression
    def eval_expr(expr: str) -> bool:
        try:
            # Replace 't' and 'f' with True and False
            expr = re.sub(r't', 'True', expr)
            expr = re.sub(r'f', 'False', expr)
            # Evaluate the expression
            return eval(expr)
        except Exception:
            return False

    # Handle nested expressions
    def handle_nested(expr: str) -> str:
        while '!(t)' in expr or '!(f)' in expr or '!(True)' in expr or '!(False)' in expr:
            expr = re.sub(r'!(t)', 'f', expr)
            expr = re.sub(r'!(f)', 't', expr)
            expr = re.sub(r'!(True)', 'False', expr)
            expr = re.sub(r'!(False)', 'True', expr)
        return expr

    # Preprocess the expression to handle nested not operations
    expression = handle_nested(expression)

    # Split the expression by operators and evaluate
    tokens = re.split(r'(\|\||&&|\!)', expression)
    result = bool_map[tokens[0]]

    for i in range(1, len(tokens), 2):
        op = tokens[i]
        val = tokens[i + 1]
        if op == '&&':
            result &= bool_map[val]
        elif op == '||':
            result |= bool_map[val]
        elif op == '!':
            result = not bool_map[val]

    return result

def expand_braces(s: str) -> list:
    def expand_range(r: str) -> list:
        start, end = map(int, r.split('-'))
        return [str(i) for i in range(start, end + 1)]

    def expand_group(group: str) -> list:
        if '{' not in group:
            return [group]
        expansions = []
        stack, cur = [], ''
        for char in group:
            if char == '{':
                stack.append(cur)
                cur = ''
            elif char == '}':
                prev = stack.pop()
                prev += cur
                cur = expand_group(prev)
            else:
                cur += char
        return [x for y in cur for x in expand_group(y)]

    def expand_list(lst: list) -> list:
        result = ['']
        for item in lst:
            result = [prev + item for prev in result]
        return result

    parts = []
    i = 0
    while i < len(s):
        if s[i] == '{':
            j = i + 1
            level = 1
            while j < len(s) and level > 0:
                if s[j] == '{':
                    level += 1
                elif s[j] == '}':
                    level -= 1
                j += 1
            parts.append(s[i:j])
            i = j
        else:
            parts.append(s[i])
            i += 1

    expansions = []
    for part in parts:
        if '{' in part:
            expansions.append(expand_group(part))
        else:
            expansions.append([part])

    result = ['']
    for exp in expansions:
        result = expand_list(exp + result)

    return sorted(result)

def expand_braces(s: str) -> list:
    """Expand a string with brace expansion. {a,b} means 'a' or 'b'. Nested braces supported. Return sorted list of all possible expansions."""

    def parse_braces(s):
        stack, cur, res = [], '', []
        for char in s:
            if char == '{':
                stack.append(res)
                res = []
            elif char == '}':
                prev = stack.pop()
                for part in prev:
                    res.append(''.join(part + [x] for x in res))
            else:
                res.append(char)
        return res

    if not s:
        return []

    parts = s.split(',')
    for i, part in enumerate(parts):
        parts[i] = parse_braces(part)

    def combine(parts):
        if not parts:
            return [""]
        result = []
        for char in parts[0]:
            for rest in combine(parts[1:]):
                result.append(char + rest)
        return result

    return sorted(combine(parts))

