    def parse_braces(brace_str):
        stack, parts, current = [], [], ""
        for char in brace_str:
            if char == '{':
                stack.append(parts)
                parts = []
            elif char == '}':
                if parts:
                    parts.append(current)
                    current = ""
                stack[-1].append(''.join(parts))
                parts = stack.pop()
            else:
                current += char
        if parts:
            parts.append(current)
        return parts[0] if parts else [current]

    def expand(parts):
        if not parts:
            return ['']
        result = []
        first_part = parts[0]
        if '{' in first_part:
            expanded = parse_braces(first_part)
            for exp in expanded:
                result.extend([exp + tail for tail in expand(parts[1:])])
        else:
            result.extend([first_part + tail for tail in expand(parts[1:])])
        return result

    return sorted(expand(s.split(',')))

def expand_braces(s: str) -> list:
    from collections import deque

    def parse_braces(s):
        stack, cur, res = [], "", []
        for char in s:
            if char == '{':
                stack.append(res)
                res = []
            elif char == '}':
                prev = stack.pop()
                for part in prev:
                    res.append(part + cur)
                cur = ""
            elif char == ',':
                if cur:
                    res.append(cur)
                    cur = ""
            else:
                cur += char
        if cur:
            res.append(cur)
        return res

    expansions = set()
    brace_indices = [i for i, char in enumerate(s) if char == '{']

    for mask in range(1, 1 << len(brace_indices)):
        new_s = list(s)
        for i, brace_index in enumerate(brace_indices):
            if mask & (1 << i):
                new_s[brace_index] = ','
            else:
                new_s[brace_index] = '|'
        expansions.update(parse_braces("".join(new_s).replace('|', '')))

    return sorted(list(expansions))

