def crack_safe(n: int, k: int) -> str:
    """Return the shortest string such that every password of length n from digits 0..k-1 appears as a substring. This is a de Bruijn sequence problem."""

    if n == 0 or k == 0:
        return ""

    def de_bruijn(k, n):
        def db(t, p):
            if p == 0: 
                paths.append(t)
            else:
                for c in range(k):
                    db(t + [c], p - 1)

        paths = []
        db([], n)
        return [''.join(map(str, path)) for path in paths]

    edges = de_bruijn(k, n - 1)
    nodes = set(edge[1:] for edge in edges)
    start_node = [node for node in nodes if node.startswith('0')][0]

    def find_path(start_node):
        path = [start_node]
        while len(path) < len(edges):
            last_char = path[-1][-1]
            next_nodes = [edge for edge in edges if edge.startswith(last_char)]
            if not next_nodes:
                break
            next_node = next_nodes[0]
            path.append(next_node)
        return ''.join(map(str, [node[0] for node in path]))

    return find_path(start_node)

