        sequence[i + n - 1] = edges[i * k]

    return ''.join(str(x) for x in sequence)

def odd_even_jumps(arr: list) -> int:
    def is_odd_jump(i):
        if i == 0 or i == len(arr) - 1:
            return True
        stack = [(arr[i], i)]
        visited = set()
        while stack:
            val, idx = stack.pop()
            if idx in visited:
                continue
            visited.add(idx)
