                memo[val] = next_idx
            if next_idx != -1:
                stack.append((arr[next_idx], next_idx))
        return False

    def is_even_jump(i):
        if i == 0 or i == len(arr) - 1:
            return True
        stack = [(arr[i], i)]
        visited = set()
        while stack:
            val, idx = stack.pop()
            if idx in visited:
