            else:
                next_idx = min((j for j in range(i + 1, len(arr)) if arr[j] <= val), default=-1)
                memo[val] = next_idx
            if next_idx != -1:
                stack.append((arr[next_idx], next_idx))
        return False

    n = len(arr)
    memo = {}
    count = 0
    for i in range(n - 1, -1, -1):
        if is_odd_jump(i):
            count += 1
    return count

