    if not arr:
        return 0

    n = len(arr)
    if n == 1:
        return 1

    # Track if we can reach the end starting from a given index
    can_reach_end = [False] * n
    can_reach_end[-1] = True

    # Sort indices by value, then by index
    indices = sorted(range(n), key=lambda i: (arr[i], i))

    # Track the highest index we can reach with an even jump
    even_reach = [False] * n
    even_reach[-1] = True

    for i in range(n - 2, -1, -1):
