                hi = mid
            else:
                lo = mid + 1
        next_index = indices[lo]

        # Check if we can reach the end from this index
        can_reach_end[i] = even_reach[next_index]

        # Update the even reach table
        if can_reach_end[i]:
            even_reach[i] = True

    return sum(can_reach_end)

