def LRUCache(capacity: int):
    """Design an LRU (Least Recently Used) cache with get(key) and put(key, value) operations, both O(1) average time."""
    def get(key):
        if key in cache:
            value = cache[key]
            cache.move_to_end(key)
            return value
        return -1

    def put(key, value):
        if key in cache:
            cache.move_to_end(key)
        cache[key] = value
        if len(cache) > capacity:
            cache.popitem(last=False)

    cache = OrderedDict()

