def top_k_frequent(nums: list, k: int) -> list:
    if not nums or k <= 0:
        return []

    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1

    import heapq
    heap = [(-freq, num) for num, freq in count.items()]
    heapq.heapify(heap)

