        a = 0
    if b == 13 or (14 <= b <= 19 and b != 15 and b != 16):
        b = 0
    return a + b

def teen_sum(a: int, b: int) -> int:
    def is_teens(n: int) -> bool:
        return 13 <= n <= 19 and n not in [15, 16]

    return (a if not is_teens(a) else 0) + (b if not is_teens(b) else 0)

def caesar_cipher(text: str, shift: int) -> str:
    result = ""
    for char in text:
        if char.isalpha():
            shift_amount = 65 if char.isupper() else 97
            result += chr((ord(char) - shift_amount + shift) % 26 + shift_amount)
        else:
            result += char
    return result

def caesar_cipher(text: str, shift: int) -> str:
    if not text:
        return text

    result = []
    for char in text:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                result.append(chr((ord(char) - ord('a') + shift_amount) % 26 + ord('a')))
            else:
                result.append(chr((ord(char) - ord('A') + shift_amount) % 26 + ord('A')))
        else:
            result.append(char)

    return ''.join(result)

def caesar_cipher(text: str, shift: int) -> str:
    shift %= 26
    result = []
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            shifted = ((ord(char) - base + shift) % 26) + base
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)

