def group_anagrams(strs: list) -> list:
    from collections import defaultdict

    anagrams = defaultdict(list)

    for word in strs:
        # Sort the word and use it as a key
        key = ''.join(sorted(word))
        anagrams[key].append(word)

    return list(anagrams.values())

