def is_valid_sudoku(board: list) -> bool:
    def is_valid(block):
        block = [i for i in block if i != '.']
        return len(block) == len(set(block))

    for row in board:
        if not is_valid(row):
            return False

    for col in zip(*board):
        if not is_valid(col):
            return False

    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            if not is_valid([board[x][y] for x in range(i, i+3) for y in range(j, j+3)]):
                return False

    return True

