def is_valid_sudoku(board: list) -> bool:
    def check_row(row):
        return len(set(filter(None, row))) == len(row) - row.count('.')

    def check_col(col):
        return len(set(filter(None, col))) == len(col) - col.count('.')

    def check_box(row_start, col_start):
        return len(set(filter(None, [board[row][col] for row in range(row_start, row_start + 3) for col in range(col_start, col_start + 3)]))) == 9 - board[row_start:row_start + 3].count(['.', '.', '.'])

    for i in range(9):
        if not (check_row(board[i]) and check_col([board[j][i] for j in range(9)]) and check_box(i - i % 3, i % 3 * 3)):
            return False
    return True

