def count_bits(n: int) -> list:
    """Return an array where ans[i] is the number of 1's in the binary representation of i, for i from 0 to n inclusive."""
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    bits_count = [0] * (n + 1)
    for i in range(1, n + 1):
        bits_count[i] = bits_count[i & (i - 1)] + 1
    return bits_count

def count_bits(n: int) -> list:
    """Return an array where ans[i] is the number of 1's in the binary representation of i, for i from 0 to n inclusive."""
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return [0]

    ans = [0] * (n + 1)
    offset = 1

    for i in range(1, n + 1):
        if offset * 2 == i:
            offset = i
        ans[i] = 1 + ans[i - offset]

    return ans

def count_bits(n: int) -> list:
