def pow_mod(base: int, exp: int, mod: int) -> int:
    """Compute (base^exp) % mod using fast modular exponentiation. Handle mod=1 (return 0). All inputs are non-negative."""
    if mod == 1:
        return 0

    result = 1
    base = base % mod

    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp = exp >> 1
        base = (base * base) % mod

    return result

