def extended_gcd(a: int, b: int) -> tuple:
    """Return (gcd, x, y) such that a*x + b*y = gcd(a, b). Handle negative inputs and zero."""
    if a == 0:
        return (b, 0, 1) if b != 0 else (0, 0, 0)
    if b == 0:
        return (a, 1, 0)

    x0, x1, y0, y1 = 1, 0, 0, 1
    while b != 0:
        q, a, b = a // b, b, a % b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1

    return (a, x0, y0)

