def extended_gcd(a: int, b: int) -> tuple:
    """Return (gcd, x, y) such that a*x + b*y = gcd(a, b). Handle negative inputs and zero."""
    if a == 0 and b == 0:
        return 0, 0, 0

    if a == 0:
        return abs(b), 0, 1 if b > 0 else -1

    if b == 0:
        return abs(a), 1 if a > 0 else -1, 0

    x0, x1, y0, y1 = 1, 0, 0, 1
    while b != 0:
        q, a, b = a // b, b, a % b
        x0, x1 = x1, x0 - q * x1
        y0, y1 = y1, y0 - q * y1

    return abs(a), x0, y0

def count_primes(n: int) -> int:
    if n <= 2:
        return 0

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n, i):
                sieve[j] = False

    return sum(sieve)

