def josephus(n: int, k: int) -> int:
    """Return the position (0-indexed) of the survivor in the Josephus problem with n people, eliminating every k-th person."""
    if n < 1:
        raise ValueError("n must be a positive integer")
    if k < 1:
        raise ValueError("k must be a positive integer")

    josephus_positions = list(range(n))
    index = 0

    while len(josephus_positions) > 1:
        index = (index + k - 1) % len(josephus_positions)
        del josephus_positions[index]
        index = 0 if index == len(josephus_positions) else index

    return josephus_positions[0]

