def clone_graph(adj_list: list) -> list:
    """Given an undirected graph as an adjacency list (0-indexed nodes), return a deep copy of the adjacency list."""

    if not adj_list:
        return []

    clone = [set() for _ in range(len(adj_list))]

    visited = {}

    def dfs(node):
        if node not in visited:
            visited[node] = len(visited)
            for neighbor in adj_list[node]:
                clone[visited[node]].add(visited.get(neighbor, len(visited)))
                dfs(neighbor)

    for node in range(len(adj_list)):
        dfs(node)

    return [set([visited[node]] + list(clone[visited[node]])) for node in range(len(adj_list))]

