def is_valid_tree(n: int, edges: list) -> bool:
    """Return True if the given graph with n nodes and edges forms a valid tree. A tree is connected and has exactly n-1 edges with no cycles."""

    if not n or not edges:
        return False

    if n != len(edges) + 1:
        return False

    visited = set()
    stack = [0]
    graph = {i: [] for i in range(n)}

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    while stack:
        node = stack.pop()
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                stack.append(neighbor)

    return len(visited) == n

def is_valid_tree(n: int, edges: list) -> bool:
    if len(edges) != n - 1:
        return False

    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    stack = [0]
    visited[0] = True

    while stack:
        node = stack.pop()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                stack.append(neighbor)
            elif visited[neighbor] and neighbor in graph[node]:
                return False

    return all(visited)

